import Foundation
import os

@main
struct TestRunner {
    static func main() async throws {
        let cache = AsyncCache<String, String>()
        let loaderCount = OSAllocatedUnfairLock(initialState: 0)

        // Test 1: 20 concurrent callers coalescing to 1 fetch
        try await withThrowingTaskGroup(of: String.self) { group in
            for _ in 0..<20 {
                group.addTask {
                    try await cache.get(key: "user_123", ttlSeconds: 10) {
                        loaderCount.withLock { $0 += 1 }
                        try await Task.sleep(nanoseconds: 50_000_000)
                        return "Alice"
                    }
                }
            }
            for try await val in group {
                assert(val == "Alice", "Returned incorrect value: \(val)")
            }
        }

        let invocations = loaderCount.withLock { $0 }
        assert(invocations == 1, "Expected 1 loader invocation due to coalescing, got \(invocations)")
        print("Swift AsyncCache Test Passed! 20 callers -> 1 invocation.")
    }
}
